<?php
 class Cache { const APP = 'mws'; const PERSISTENT_ID = 'redis'; const DEFAULT_PORT = 7379; const CONNECT_TIMEOUT = 2; const VAR_EXPIRE_TIME = 0; const FILE_PREFIX = 'file:'; const FILE_EXPIRE_TIME = 60; const SESSION_PREFIX = 'sess:'; const SESSION_EXPIRE_TIME = 24 * 60 * 60; const SESSIONS_KEY = 'sessions'; const GC_TIMESTAMP_KEY = 'gc_timestamp'; const GC_INTERVAL = 15 * 60; private static ?Redis $redis = null; private static ?string $sessionId = null; private static bool $enabled = true; private static function init(): void { $redis = new Redis(); $host = (string) ini_get('redis.host') ?: '127.0.0.1'; $port = (int) ini_get('redis.port') ?: self::DEFAULT_PORT; $timeout = (float) ini_get('redis.connect_timeout') ?: self::CONNECT_TIMEOUT; if (!$redis->pconnect($host, $port, $timeout, self::PERSISTENT_ID)) { throw new ErrorException("Ошибка подключения к серверу Redis [$host:$port]", E_FATAL_ERROR); } $redis->setOption(Redis::OPT_PREFIX, self::APP . ':'); $redis->setOption(Redis::OPT_SERIALIZER, Redis::SERIALIZER_NONE); self::$redis = $redis; } public static function enable(): void { self::$enabled = true; } public static function disable(): void { self::$enabled = false; } public static function getInstance(): ?Redis { if (self::$enabled) { if (!self::$redis) { self::init(); } return self::$redis; } return null; } public static function get(string $key): mixed { return ($redis = self::getInstance()) ? igbinary_unserialize($redis->get($key)) : false; } public static function set(string $key, mixed $data, int $expire = self::VAR_EXPIRE_TIME): bool { if (($redis = self::getInstance())) { if ($data !== false) { return $redis->set($key, igbinary_serialize($data), ['ex' => $expire]); } else { $redis->unlink($key); return true; } } return false; } public static function readFile(string $filename, int $expire = self::FILE_EXPIRE_TIME): mixed { if (($redis = self::getInstance())) { $key = self::FILE_PREFIX . $filename; $data = igbinary_unserialize($redis->get($key)); if ($data === false) { $data = is_file($filename) ? file_get_contents($filename) : false; if ($data !== false) { $redis->set($key, igbinary_serialize($data), ['ex' => $expire]); } else { $redis->unlink($key); } } } else { $data = is_file($filename) ? file_get_contents($filename) : false; } return $data; } public static function save(): void { self::getInstance()->save(); } public static function sessionId(?string $id = null): false|string|null { if (($redis = self::getInstance())) { if ($id) { self::$sessionId = $id; } if (self::$sessionId) { return self::$sessionId; } for ($i = 0; $i < 10; $i++) { $sessionId = self::sessionGenerateId(); if ($redis->set(self::sessionKey($sessionId), igbinary_serialize([]), ['nx', 'ex' => self::SESSION_EXPIRE_TIME])) { return (self::$sessionId = $sessionId); } } } return false; } public static function sessionStart(): bool { if (($redis = self::getInstance()) && ($sessionId = self::$sessionId)) { $data = igbinary_unserialize($redis->get(self::sessionKey($sessionId))); if ($data !== false) { $_SESSION = $data; return true; } } return false; } public static function sessionDestroy(): void { if (($redis = self::$redis) && ($sessionId = self::$sessionId)) { $key = self::sessionKey($sessionId); $redis->multi(Redis::PIPELINE); $redis->unlink($key); $redis->hDel(self::SESSIONS_KEY, $key); $redis->exec(); self::$sessionId = null; } } public static function sessionWrite(): void { if (($redis = self::$redis) && ($sessionId = self::$sessionId)) { $redis->multi(Redis::PIPELINE); if (isset($_SESSION['accessTime'])) { $redis->hSet(self::SESSIONS_KEY, $sessionId, $_SESSION['accessTime']); } $redis->set(self::sessionKey($sessionId), igbinary_serialize($_SESSION), ['ex' => self::SESSION_EXPIRE_TIME]); $redis->exec(); } } public static function getSessions(): array { if ($redis = self::$redis) { return $redis->hGetAll(self::SESSIONS_KEY); } return []; } public static function garbageCollectionSessions(): array { $ret = []; if ($redis = self::$redis) { $timestamp = $redis->get(self::GC_TIMESTAMP_KEY); if (!$timestamp || (time() - strtotime($timestamp)) >= self::GC_INTERVAL) { $redis->set(self::GC_TIMESTAMP_KEY, date('Y-m-d H:i:s')); $sessions = self::getSessions(); foreach ($sessions as $id => $accessTime) { if ((time() - strtotime($accessTime)) >= self::SESSION_EXPIRE_TIME) { $redis->multi(Redis::PIPELINE); $redis->unlink($id); $redis->hDel(self::SESSIONS_KEY, $id); $redis->exec(); } else if (!$redis->exists($id)) { $redis->hDel(self::SESSIONS_KEY, $id); } else { $ret[$id] = $accessTime; } } } else { $ret = self::getSessions(); } } return $ret; } public static function sessionGenerateId(): string { return md5(microtime() . rand() . uniqid()); } public static function sessionKey(string $sessionId): string { return self::SESSION_PREFIX . $sessionId; } }